573	/****************************************************************************
574	 * Name: gt9xx_open
575	 *
576	 * Description:
577	 *   Open the Touch Panel Device.  If this is the first open, we power on
578	 *   the Touch Panel, probe for the Touch Panel and enable Touch Panel
579	 *   Interrupts.
580	 *
581	 * Input Parameters:
582	 *   filep - File Struct for Touch Panel
583	 *
584	 * Returned Value:
585	 *   Zero (OK) on success; a negated errno value is returned on any failure.
586	 *
587	 ****************************************************************************/
588	
589	static int gt9xx_open(FAR struct file *filep)
590	{
591	  FAR struct inode *inode;
592	  FAR struct gt9xx_dev_s *priv;
593	  unsigned int use_count;
594	  int ret;
595	
596	  /* Get the Touch Panel Device */
597	
598	  iinfo("\n");
599	  inode = filep->f_inode;
600	  DEBUGASSERT(inode->i_private);
601	  priv = inode->i_private;
602	
603	  /* Begin Mutex: Lock to prevent concurrent update to Reference Count */
604	
605	  ret = nxmutex_lock(&priv->devlock);
606	  if (ret < 0)
607	    {
608	      ierr("Lock Mutex failed: %d\n", ret);
609	      return ret;
610	    }
611	
612	  /* Get next Reference Count */
613	
614	  use_count = priv->cref + 1;
615	  DEBUGASSERT(use_count < UINT8_MAX && use_count > priv->cref);
616	  if (use_count == 1)
617	    {
618	      /* If first user, power on the Touch Panel */
619	
620	      DEBUGASSERT(priv->board->set_power != NULL);
621	      ret = priv->board->set_power(priv->board, true);
622	      if (ret < 0)
623	        {
624	          goto out_lock;
625	        }
626	
627	      /* Let Touch Panel power up before probing */
628	
629	      nxsig_usleep(100 * 1000);
630	
631	      /* Check that Touch Panel exists on I2C */
632	
633	      ret = gt9xx_probe_device(priv);
634	      if (ret < 0)
635	        {
636	          /* No such device, power off the Touch Panel */
637	
638	          priv->board->set_power(priv->board, false);
639	          goto out_lock;
640	        }
641	
642	      priv->int_pending = false;
643	      priv->touched = false;
644	
645	      /* Enable Touch Panel Interrupts */
646	
647	      DEBUGASSERT(priv->board->irq_enable);
648	      priv->board->irq_enable(priv->board, true);
649	    }
650	
651	  /* Set the Reference Count */
652	
653	  priv->cref = use_count;
654	
655	  /* End Mutex: Unlock to allow update to Reference Count */
656	
657	out_lock:
658	  nxmutex_unlock(&priv->devlock);
659	  return ret;
660	}
