662	/****************************************************************************
663	 * Name: gt9xx_close
664	 *
665	 * Description:
666	 *   Close the Touch Panel Device.  If this is the final close, we disable
667	 *   Touch Panel Interrupts and power off the Touch Panel.
668	 *
669	 * Input Parameters:
670	 *   filep - File Struct for Touch Panel
671	 *
672	 * Returned Value:
673	 *   Zero (OK) on success; a negated errno value is returned on any failure.
674	 *
675	 ****************************************************************************/
676	
677	static int gt9xx_close(FAR struct file *filep)
678	{
679	  FAR struct inode *inode;
680	  FAR struct gt9xx_dev_s *priv;
681	  int use_count;
682	  int ret;
683	
684	  /* Get the Touch Panel Device */
685	
686	  iinfo("\n");
687	  inode = filep->f_inode;
688	  DEBUGASSERT(inode->i_private);
689	  priv = inode->i_private;
690	
691	  /* Begin Mutex: Lock to prevent concurrent update to Reference Count */
692	
693	  ret = nxmutex_lock(&priv->devlock);
694	  if (ret < 0)
695	    {
696	      ierr("Lock Mutex failed: %d\n", ret);
697	      return ret;
698	    }
699	
700	  /* Decrement the Reference Count */
701	
702	  use_count = priv->cref - 1;
703	  DEBUGASSERT(use_count >= 0);
704	  if (use_count == 0)
705	    {
706	      /* If final user, disable Touch Panel Interrupts */
707	
708	      DEBUGASSERT(priv->board && priv->board->irq_enable);
709	      priv->board->irq_enable(priv->board, false);
710	
711	      /* Power off the Touch Panel */
712	
713	      DEBUGASSERT(priv->board->set_power);
714	      priv->board->set_power(priv->board, false);
715	    }
716	
717	  /* Set the Reference Count */
718	
719	  priv->cref = use_count;
720	
721	  /* End Mutex: Unlock to allow update to Reference Count */
722	
723	  nxmutex_unlock(&priv->devlock);
724	  return OK;
725	}
