872	/****************************************************************************
873	 * Name: gt9xx_isr_handler
874	 *
875	 * Description:
876	 *   Interrupt Handler for Touch Panel.
877	 *
878	 * Input Parameters:
879	 *   irq     - IRQ Number
880	 *   context - IRQ Context
881	 *   arg     - Touch Panel Device
882	 *
883	 * Returned Value:
884	 *   Zero (OK) on success; a negated errno value is returned on any failure.
885	 *
886	 ****************************************************************************/
887	
888	static int gt9xx_isr_handler(int irq, FAR void *context, FAR void *arg)
889	{
890	  FAR struct gt9xx_dev_s *priv = (FAR struct gt9xx_dev_s *)arg;
891	  irqstate_t flags;
892	
893	  DEBUGASSERT(priv);
894	
895	  /* Begin Critical Section */
896	
897	  flags = enter_critical_section();
898	
899	  /* Set the Interrupt Pending Flag */
900	
901	  priv->int_pending = true;
902	
903	  /* End Critical Section */
904	
905	  leave_critical_section(flags);
906	
907	  /* Notify the Poll Waiters */
908	
909	  poll_notify(priv->fds, CONFIG_INPUT_GT9XX_NPOLLWAITERS, POLLIN);
910	  return OK;
911	}
