767	/****************************************************************************
768	 * Name: gt9xx_poll
769	 *
770	 * Description:
771	 *   Setup or teardown a poll for the Touch Panel Device.
772	 *
773	 * Input Parameters:
774	 *   filep - File Struct for Touch Panel
775	 *   fds   - The structure describing the events to be monitored, OR NULL if
776	 *           this is a request to stop monitoring events.
777	 *   setup - true: Setup the poll; false: Teardown the poll
778	 *
779	 * Returned Value:
780	 *   Zero (OK) on success; a negated errno value is returned on any failure.
781	 *
782	 ****************************************************************************/
783	
784	static int gt9xx_poll(FAR struct file *filep, FAR struct pollfd *fds,
785	                      bool setup)
786	{
787	  FAR struct gt9xx_dev_s *priv;
788	  FAR struct inode *inode;
789	  bool pending;
790	  int ret = 0;
791	  int i;
792	
793	  /* Get the Touch Panel Device */
794	
795	  iinfo("setup=%d\n", setup);
796	  DEBUGASSERT(fds);
797	  inode = filep->f_inode;
798	  DEBUGASSERT(inode->i_private);
799	  priv = inode->i_private;
800	
801	  /* Begin Mutex: Lock to prevent concurrent update to Poll Waiters */
802	
803	  ret = nxmutex_lock(&priv->devlock);
804	  if (ret < 0)
805	    {
806	      ierr("Lock Mutex failed: %d\n", ret);
807	      return ret;
808	    }
809	
810	  if (setup)
811	    {
812	      /* If Poll Setup: Ignore waits that do not include POLLIN */
813	
814	      if ((fds->events & POLLIN) == 0)
815	        {
816	          ret = -EDEADLK;
817	          goto out;
818	        }
819	
820	      /* Find an available slot for the Poll Waiter */
821	
822	      for (i = 0; i < CONFIG_INPUT_GT9XX_NPOLLWAITERS; i++)
823	        {
824	          /* Found an available slot */
825	
826	          if (!priv->fds[i])
827	            {
828	              /* Bind the poll structure and this slot */
829	
830	              priv->fds[i] = fds;
831	              fds->priv = &priv->fds[i];
832	              break;
833	            }
834	        }
835	
836	      if (i >= CONFIG_INPUT_GT9XX_NPOLLWAITERS)
837	        {
838	          /* No slots available */
839	
840	          fds->priv = NULL;
841	          ret = -EBUSY;
842	        }
843	      else
844	        {
845	          /* If Interrupt Pending is set, notify the Poll Waiters */
846	
847	          pending = priv->int_pending;
848	          if (pending)
849	            {
850	              poll_notify(&fds, 1, POLLIN);
851	            }
852	        }
853	    }
854	  else if (fds->priv)
855	    {
856	      /* If Poll Teardown: Remove the poll setup */
857	
858	      FAR struct pollfd **slot = (FAR struct pollfd **)fds->priv;
859	      DEBUGASSERT(slot != NULL);
860	
861	      *slot = NULL;
862	      fds->priv = NULL;
863	    }
864	
865	  /* End Mutex: Unlock to allow update to Poll Waiters */
866	
867	out:
868	  nxmutex_unlock(&priv->devlock);
869	  return ret;
870	}
