  lv_display_set_flush_cb(result->disp, preview_flush);

  result->indev = lv_indev_create();
  lv_indev_set_type(result->indev, LV_INDEV_TYPE_POINTER);
  lv_indev_set_read_cb(result->indev, preview_read);
}

